function theMaximumAchievableX(num, t) {
  // Track every possible difference x - num after each operation and test candidates from high to low.
  const canMeet = (x) => {
    let diffs = new Set([x - num]);
    for (let step = 0; step <= t; step++) {
      if (diffs.has(0)) return true;
      const next = new Set();
      for (const d of diffs) for (const dx of [-1, 1]) for (const dn of [-1, 1]) next.add(d + dx - dn);
      diffs = next;
    }
    return false;
  };
  for (let x = num + 4 * t + 4; ; x--) if (canMeet(x)) return x;
}

